import pandas as pd


def apply(df, ctx):
    keep = df["rater1"].notna() & df["rater2"].notna() & df["skin_tone"].notna()
    out = df[keep].copy()
    dyads = out.groupby("refNum")["refNum"].transform("size")
    return out[dyads >= 22].copy()
